S=ut5r2-board; E=/Users/dct/.factory/missions/e194b9e3-6a67-42b9-bfc9-dd4e1ac23b0c/evidence/m5/cross008-board; cd $E
cat > /tmp/ut-m5r2/board/probe2.js <<'EOF'
(() => {
  const q = (s, r=document) => Array.from(r.querySelectorAll(s));
  const t = s => { const e = document.querySelector(s); return e ? e.textContent.trim() : null; };
  const lanes = q('section.lane').map(l => ({
    aria: l.getAttribute('aria-label'), lane: l.getAttribute('data-lane'),
    count: (l.querySelector('.count')||{}).textContent,
    cards: q('article.card', l).map(c => c.getAttribute('aria-label'))}));
  const labels = q('[aria-label]').map(e=>e.getAttribute('aria-label')).filter(a=>/tray|event|unknown|status|telemetry/i.test(a));
  return JSON.stringify({cardsTotal: q('article.card').length, lanes, labels: Array.from(new Set(labels)),
    tray: t('[aria-label="tray-count"]'), unknown: t('[aria-label="unknown-count"]'), events: t('[aria-label="event-count"]')}, null, 1);
})()
EOF
agent-browser --session $S eval --stdin < /tmp/ut-m5r2/board/probe2.js | python3 -c 'import sys,json; print(json.loads(sys.stdin.read()))' | tee dom-board-browser-raw.json | head -c 3000
